def solve(grid):
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    visited = [[False]*m for _ in range(n)]
    def dfs(i,j):
        stack = [(i,j)]
        while stack:
            x,y = stack.pop()
            if x<0 or x>=n or y<0 or y>=m:
                continue
            if visited[x][y] or grid[x][y]==0:
                continue
            visited[x][y]=True
            stack.append((x+1,y))
            stack.append((x-1,y))
            stack.append((x,y+1))
            stack.append((x,y-1))
    count=0
    for i in range(n):
        for j in range(m):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count+=1
    return count

